using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;

namespace XmlA1 {
 sealed class KeyBatchForm:Form {
  readonly KeyQueueStore store;readonly string actor;readonly int env,uf;TextBox input,issues;Label preview,summary;DataGridView jobs;CheckBox resume,queueScience,queueConfirm;KeyPaste parsed=new KeyPaste();
  public KeyBatchForm(KeyQueueStore queueStore,string cnpj,int environment,int stateCode) {
   store=queueStore;actor=Rules.Cnpj(cnpj);env=environment;uf=stateCode;Text="Consultar chaves em lote — "+actor;Size=new Size(1020,790);MinimumSize=new Size(900,700);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(242,246,249);
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=8,Padding=new Padding(16)};Controls.Add(layout);foreach(int h in new[]{38,145,28,60,30})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,96));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));
   layout.Controls.Add(new Label{Text="Cole as células da planilha abaixo (Ctrl+V). Pode colar várias linhas e colunas.",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,0);
   input=new TextBox{Multiline=true,AcceptsReturn=true,AcceptsTab=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,Font=new Font("Consolas",10),MaxLength=2*1024*1024,AccessibleName="Chaves copiadas da planilha"};input.TextChanged+=delegate{ValidatePaste();};layout.Controls.Add(input,0,1);
   preview=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Color.FromArgb(0,122,104),Text="Cole as chaves completas, com 44 posições."};layout.Controls.Add(preview,0,2);
   issues=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,ForeColor=Color.FromArgb(145,66,22),AccessibleName="Problemas encontrados na colagem"};layout.Controls.Add(issues,0,3);
   summary=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};layout.Controls.Add(summary,0,4);
   jobs=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,BackgroundColor=Color.White,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};Column("Key","Chave",270);Column("Status","Resultado",95);Column("Code","SEFAZ",45);Column("ConfirmationCode","Confirmação",60);Column("Attempts","Tentativas",50);Column("Message","Detalhes",200);jobs.RowTemplate.Height=28;layout.Controls.Add(jobs,0,5);
   var options=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};resume=new CheckBox{Text="Baixar automaticamente os XMLs pendentes nas próximas janelas, enquanto aberto com o A1",AutoSize=true,Checked=true};queueScience=new CheckBox{Text="Dar Ciência da Operação quando necessária para as chaves desta fila",AutoSize=true,Checked=true};queueConfirm=new CheckBox{Text="Reconheço as operações das chaves digitadas/coladas; confirmar (210200) se faltar XML",AutoSize=true,Checked=true};queueScience.Checked=false;queueScience.Enabled=false;queueConfirm.CheckedChanged+=delegate{queueScience.Enabled=!queueConfirm.Checked;if(queueConfirm.Checked)queueScience.Checked=false;};options.Controls.Add(resume);options.Controls.Add(queueConfirm);options.Controls.Add(queueScience);layout.Controls.Add(options,0,6);
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};layout.Controls.Add(buttons,0,7);
   Button add=Button("Validar e adicionar",160);add.Click+=delegate{try{ValidatePaste();if(parsed.Keys.Count==0)throw new InvalidOperationException("Não há chaves válidas na colagem.");using(store.Lock(actor,env)){var q=store.Load(actor,env);q.DownloadAll=true;q.AutoContinue=false;int added=q.AddUserKeys(parsed.Keys);store.Save(actor,env,q);preview.Text=added+" adicionada(s); "+(parsed.Keys.Count-added)+" já existiam na fila.";}Reload();}catch(Exception ex){ShowError(ex);}};buttons.Controls.Add(add);
   Button start=Button("Baixar / continuar XMLs",175);start.Click+=delegate{try{using(store.Lock(actor,env)){var q=store.Load(actor,env);q.StartDownloads();if(q.Pending==0)throw new InvalidOperationException("Adicione chaves válidas ou recoloque resultados na fila.");if(queueConfirm.Checked){if(!q.Jobs.Any(j=>j.UserSupplied&&j.Status=="Pendente"))throw new InvalidOperationException("Cole novamente e adicione as chaves das notas que você reconhece. Chaves antigas ou adicionadas automaticamente não recebem confirmação sem essa identificação.");if(q.ConfirmationConsent==DateTime.MinValue){if(MessageBox.Show(this,"Confirmar as operações das chaves fornecidas por você?\n\nCNPJ: "+actor+"\nAmbiente: "+(env==1?"Produção":"Homologação")+"\n\nVocê declara que reconhece como realizadas as operações das chaves digitadas/coladas nesta fila. Se faltar o XML completo, será enviada Confirmação da Operação (210200), assinada com o A1.\n\nO prazo de 10 dias da ciência não limita essa confirmação. A SEFAZ valida o prazo próprio e os demais requisitos. Após o aceite, o programa consultará o XML completo.\n\nResumos fora desta lista não serão confirmados.","Confirmar e baixar XMLs",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;q.ConfirmationConsent=DateTime.UtcNow;}}if(!queueConfirm.Checked&&queueScience.Checked&&q.ScienceConsent==DateTime.MinValue){if(MessageBox.Show(this,"Baixar XMLs com ciência automática quando necessária?\n\nCNPJ: "+actor+"\nAmbiente: "+(env==1?"Produção":"Homologação")+"\n\nO programa tentará baixar cada XML antes de manifestar. Se receber só o resumo, poderá enviar Ciência da Operação (210210), assinada com o A1, apenas para as chaves desta fila.\n\nSe a ciência for rejeitada por prazo, continuará buscando o XML sem reenviar o evento. A liberação depende da SEFAZ. Não será enviada Confirmação da Operação automaticamente.","Baixar XMLs da fila",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;q.ScienceConsent=DateTime.UtcNow;}q.ConfirmForDownload=queueConfirm.Checked;q.ScienceForDownload=!queueConfirm.Checked&&queueScience.Checked;q.AutoContinue=resume.Checked;if(uf>0)q.Uf=uf;if(q.Uf==0)throw new InvalidOperationException("Selecione a UF da empresa na janela principal.");store.Save(actor,env,q);}DialogResult=DialogResult.OK;}catch(Exception ex){ShowError(ex);}};buttons.Controls.Add(start);
   Button retry=Button("Recolocar selecionadas",175);retry.Click+=delegate{try{var chosen=jobs.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.DataBoundItem as KeyJob).Where(j=>j!=null).Select(j=>j.Key).ToArray();using(store.Lock(actor,env)){var q=store.Load(actor,env);foreach(var j in q.Jobs.Where(j=>chosen.Contains(j.Key))){j.Status="Pendente";j.Code="";j.Message="Reconsulta solicitada pelo usuário.";j.NotBefore=DateTime.MinValue;j.XmlChecks=0;}q.AutoContinue=false;store.Save(actor,env,q);}Reload();}catch(Exception ex){ShowError(ex);}};buttons.Controls.Add(retry);
   Button results=Button("Exportar resultados",155);results.Click+=Export;buttons.Controls.Add(results);
   Button pause=Button("Pausar automática",145);pause.Click+=delegate{try{using(store.Lock(actor,env)){var q=store.Load(actor,env);q.AutoContinue=false;store.Save(actor,env,q);}resume.Checked=false;Reload();}catch(Exception ex){ShowError(ex);}};buttons.Controls.Add(pause);
   Shown+=delegate{try{Reload();var q=store.Load(actor,env);resume.Checked=q.Jobs.Count==0||!q.DownloadAll||q.AutoContinue;queueConfirm.Checked=q.ConfirmationConsent==DateTime.MinValue||q.ConfirmForDownload;queueScience.Enabled=!queueConfirm.Checked;queueScience.Checked=!queueConfirm.Checked&&(q.ScienceConsent==DateTime.MinValue||q.ScienceForDownload);}catch(Exception ex){ShowError(ex);}};
  }
  Button Button(string text,int width){return new Button{Text=text,Width=width,Height=36,Margin=new Padding(2,4,5,2)};}
  void Column(string property,string title,int width){jobs.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=property,HeaderText=title,FillWeight=width,MinimumWidth=property=="ConfirmationCode"?100:property=="Attempts"?85:45,SortMode=DataGridViewColumnSortMode.NotSortable});}
  void ShowError(Exception ex){MessageBox.Show(this,ex.Message,"Consulta em lote",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  void ValidatePaste(){try{parsed=KeyPaste.Parse(input.Text);preview.Text=parsed.Keys.Count+" válida(s) · "+parsed.Duplicates+" repetida(s) · "+parsed.Invalid.Count+" inválida(s) · "+parsed.Ignored+" célula(s) ignorada(s)";issues.Text=String.Join(System.Environment.NewLine,parsed.Invalid.Take(100));if(parsed.Scientific>0)issues.AppendText(System.Environment.NewLine+"A planilha transformou chaves em notação científica. Recupere as chaves completas na origem e mantenha a coluna como Texto; mudar o formato depois não recupera dígitos perdidos.");}catch(Exception ex){parsed=new KeyPaste();preview.Text=ex.Message;issues.Text="";}}
  void Reload(){var q=store.Load(actor,env);jobs.DataSource=q.Jobs;summary.Text=q.Jobs.Count+" chave(s) na fila · "+q.Pending+" pendente(s)"+(q.Next>DateTime.UtcNow?" · próxima consulta após "+q.Next.ToLocalTime().ToString("dd/MM HH:mm:ss"):"")+" · limite: 20 consultas/hora";}
  void Export(object sender,EventArgs e){try{using(var d=new SaveFileDialog{Filter="Planilha Excel (*.xlsx)|*.xlsx",FileName="Resultados_chaves_"+actor+".xlsx"})if(d.ShowDialog(this)==DialogResult.OK){var q=store.Load(actor,env);QueueSpreadsheet.Save(d.FileName,q.Jobs);}}catch(Exception ex){ShowError(ex);}}
 }
}
